  `LAST_NAME` varchar(255) DEFAULT NULL,
  `LEAD_SOURCE` varchar(255) DEFAULT NULL,
  `LEVEL_C` varchar(255) DEFAULT NULL,
  `MAILING_ADDRESS_CITY` varchar(255) DEFAULT NULL,
  `MAILING_ADDRESS_COUNTRY` varchar(255) DEFAULT NULL,
  `MAILING_ADDRESS_POSTAL_CODE` varchar(255) DEFAULT NULL,
  `MAILING_ADDRESS_STATE` varchar(255) DEFAULT NULL,
  `MAILING_ADDRESS_STREET` varchar(255) DEFAULT NULL,
  `MAILING_CITY` varchar(255) DEFAULT NULL,
  `MAILING_COUNTRY` varchar(255) DEFAULT NULL,
  `MAILING_POSTAL_CODE` varchar(255) DEFAULT NULL,
  `MAILING_STATE` varchar(255) DEFAULT NULL,
  `MAILING_STREET` varchar(255) DEFAULT NULL,
  `MOBILE_PHONE` varchar(255) DEFAULT NULL,
