  `OTHER_ADDRESS_CITY` varchar(255) DEFAULT NULL,
  `OTHER_ADDRESS_COUNTRY` varchar(255) DEFAULT NULL,
  `OTHER_ADDRESS_POSTAL_CODE` varchar(255) DEFAULT NULL,
  `OTHER_ADDRESS_STATE` varchar(255) DEFAULT NULL,
  `OTHER_ADDRESS_STREET` varchar(255) DEFAULT NULL,
  `OTHER_CITY` varchar(255) DEFAULT NULL,
  `OTHER_COUNTRY` varchar(255) DEFAULT NULL,
  `OTHER_PHONE` varchar(255) DEFAULT NULL,
  `OTHER_POSTAL_CODE` varchar(255) DEFAULT NULL,
  `OTHER_STATE` varchar(255) DEFAULT NULL,
