DROP TABLE IF EXISTS `opportunity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `opportunity` (
  `ACCOUNT_ID` varchar(18) DEFAULT NULL,
  `AMOUNT` decimal(18,2) DEFAULT NULL,
  `CLOSE_DATE` date DEFAULT NULL,
  `CREATED_BY_ID` varchar(18) DEFAULT NULL,
  `CREATED_DATE` datetime DEFAULT NULL,
  `CURRENT_GENERATORS_C` varchar(255) DEFAULT NULL,
  `DELIVERY_INSTALLATION_STATUS_C` varchar(255) DEFAULT NULL,
  `EXPECTED_REVENUE` decimal(18,2) DEFAULT NULL,
  `FISCAL` varchar(255) DEFAULT NULL,
  `FISCAL_QUARTER` int DEFAULT NULL,
  `FISCAL_YEAR` int DEFAULT NULL,
  `FORECAST_CATEGORY` varchar(255) DEFAULT NULL,
  `FORECAST_CATEGORY_NAME` varchar(255) DEFAULT NULL,
  `HAS_OPEN_ACTIVITY` tinyint(1) DEFAULT NULL,
  `HAS_OPPORTUNITY_LINE_ITEM` tinyint(1) DEFAULT NULL,
  `HAS_OVERDUE_TASK` tinyint(1) DEFAULT NULL,
  `OPPORTUNITY_ID` varchar(18) NOT NULL,
  `IS_CLOSED` tinyint(1) DEFAULT NULL,
  `IS_DELETED` tinyint(1) DEFAULT NULL,
  `IS_PRIVATE` tinyint(1) DEFAULT NULL,
  `IS_WON` tinyint(1) DEFAULT NULL,
  `LAST_MODIFIED_BY_ID` varchar(18) DEFAULT NULL,
  `LAST_MODIFIED_DATE` datetime DEFAULT NULL,
  `LEAD_SOURCE` varchar(255) DEFAULT NULL,
  `MAIN_COMPETITORS_C` varchar(255) DEFAULT NULL,
  `NAME` varchar(255) DEFAULT NULL,
  `ORDER_NUMBER_C` varchar(255) DEFAULT NULL,
  `OWNER_ID` varchar(18) DEFAULT NULL,
  `PROBABILITY` decimal(5,2) DEFAULT NULL,
  `STAGE_NAME` varchar(255) DEFAULT NULL,
  `SYSTEM_MODSTAMP` datetime DEFAULT NULL,
  `TRACKING_NUMBER_C` varchar(255) DEFAULT NULL,
  `TYPE` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`OPPORTUNITY_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

