DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `ABOUT_ME` text,
  `ADDRESS_COUNTRY` varchar(255) DEFAULT NULL,
  `ALIAS` varchar(255) DEFAULT NULL,
  `BADGE_TEXT` varchar(255) DEFAULT NULL,
  `BANNER_PHOTO_URL` varchar(1024) DEFAULT NULL,
  `COMMUNITY_NICKNAME` varchar(255) DEFAULT NULL,
  `COMPANY_NAME` varchar(255) DEFAULT NULL,
  `COUNTRY` varchar(255) DEFAULT NULL,
  `CREATED_BY_ID` varchar(18) DEFAULT NULL,
  `CREATED_DATE` datetime DEFAULT NULL,
  `DEFAULT_GROUP_NOTIFICATION_FREQUENCY` varchar(255) DEFAULT NULL,
  `DIGEST_FREQUENCY` varchar(255) DEFAULT NULL,
  `EMAIL` varchar(255) DEFAULT NULL,
  `EMAIL_ENCODING_KEY` varchar(255) DEFAULT NULL,
  `EMAIL_PREFERENCES_AUTO_BCC` tinyint(1) DEFAULT NULL,
  `EMAIL_PREFERENCES_AUTO_BCC_STAY_IN_TOUCH` tinyint(1) DEFAULT NULL,
  `EMAIL_PREFERENCES_STAY_IN_TOUCH_REMINDER` tinyint(1) DEFAULT NULL,
  `FIRST_NAME` varchar(255) DEFAULT NULL,
  `FORECAST_ENABLED` tinyint(1) DEFAULT NULL,
  `FULL_PHOTO_URL` varchar(1024) DEFAULT NULL,
